import{_ as a,o as r,c as e,j as t,a as i,a5 as l}from"./chunks/framework.BF53ZjCA.js";const b=JSON.parse('{"title":"给一颗宝石找到它的坐标","description":"从材料、结构、光学现象与颜色成因，建立宝石分类的第一张地图。","frontmatter":{"title":"给一颗宝石找到它的坐标","description":"从材料、结构、光学现象与颜色成因，建立宝石分类的第一张地图。"},"headers":[],"relativePath":"zh/classification/intro.md","filePath":"zh/classification/intro.md","lastUpdated":1789241305000}'),s={name:"zh/classification/intro.md"};function o(n,d,h,c,p,m){return r(),e("div",null,[...d[0]||(d[0]=[t("h1",{id:"给一颗宝石找到它的坐标",tabindex:"-1"},[i("给一颗宝石找到它的坐标 "),t("a",{class:"header-anchor",href:"#给一颗宝石找到它的坐标","aria-label":'Permalink to "给一颗宝石找到它的坐标"'},"​")],-1),t("blockquote",null,[t("p",null,"从材料、结构到光学现象，建立宝石世界的第一张地图。")],-1),t("p",null,"分类不是给宝石贴上一个标签，而是回答四个问题：它是什么、如何形成、如何呈现光，以及我们应该怎样继续认识它。",-1),t("div",{class:"classification-map",role:"list","aria-label":"宝石分类的四个观察入口"},[t("a",{class:"classification-map__item",href:"./mineral-groups/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"01"),t("strong",null,"材料属性"),t("span",null,"它是什么")]),t("a",{class:"classification-map__item",href:"./crystal-systems/cubic",role:"listitem"},[t("span",{class:"classification-map__index"},"02"),t("strong",null,"晶体结构"),t("span",null,"它如何排列")]),t("a",{class:"classification-map__item",href:"./optical-phenomena/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"03"),t("strong",null,"光学现象"),t("span",null,"它如何发光")]),t("a",{class:"classification-map__item",href:"./color-causes/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"04"),t("strong",null,"颜色成因"),t("span",null,"它为何有色")])],-1),l('<h2 id="_01-·-它是什么-材料与成因" tabindex="-1">01 · 它是什么：材料与成因 <a class="header-anchor" href="#_01-·-它是什么-材料与成因" aria-label="Permalink to &quot;01 · 它是什么：材料与成因&quot;">​</a></h2><p>许多天然宝石与矿物有关，但宝石材料并不只有矿物。GemAtlas 将材料先按来源与性质区分，再通过晶体结构、光学现象和颜色成因继续细分。</p><table tabindex="0"><thead><tr><th>材料类别</th><th>判断重点</th><th>代表材料</th></tr></thead><tbody><tr><td>天然矿物</td><td>天然形成，具有相对明确的化学组成与晶体结构</td><td>刚玉、绿柱石、石英、金刚石</td></tr><tr><td>类矿物 / 非晶质材料</td><td>有宝石属性，但不具备完整的长程晶体结构</td><td>欧泊、黑曜石</td></tr><tr><td>有机材料</td><td>由生物活动或生物成因形成</td><td>珍珠、琥珀、珊瑚</td></tr><tr><td>实验室合成材料</td><td>在实验室制造，化学与结构可接近天然对应物</td><td>合成红宝石、合成祖母绿、CVD 钻石</td></tr><tr><td>仿制品</td><td>用另一种材料模拟目标宝石的外观</td><td>立方氧化锆、玻璃、莫桑石</td></tr></tbody></table><h3 id="矿物族中的代表宝石" tabindex="-1">矿物族中的代表宝石 <a class="header-anchor" href="#矿物族中的代表宝石" aria-label="Permalink to &quot;矿物族中的代表宝石&quot;">​</a></h3><table tabindex="0"><thead><tr><th>矿物族</th><th>代表宝石</th></tr></thead><tbody><tr><td>刚玉</td><td>红宝石、蓝宝石</td></tr><tr><td>绿柱石</td><td>祖母绿、海蓝宝、摩根石</td></tr><tr><td>石英</td><td>紫晶、黄水晶、水晶</td></tr><tr><td>石榴石</td><td>沙弗莱、翠榴石、铁铝榴石</td></tr><tr><td>电气石</td><td>帕拉伊巴、西瓜碧玺</td></tr><tr><td>尖晶石</td><td>红色、蓝色尖晶石</td></tr><tr><td>金刚石</td><td>无色钻石、彩钻</td></tr><tr><td>长石</td><td>月光石、拉长石、天河石</td></tr><tr><td>黝帘石</td><td>坦桑石</td></tr><tr><td>蛋白石</td><td>贵欧泊、火欧泊</td></tr></tbody></table><blockquote><p>“贵重宝石”和“半贵重宝石”是传统商业语境中的称呼，不是现代宝石学的严格科学分类。判断价值时，更应关注稀有度、美观度、耐久性、处理情况与市场需求。</p></blockquote><h2 id="_02-·-它如何排列-晶系与结构" tabindex="-1">02 · 它如何排列：晶系与结构 <a class="header-anchor" href="#_02-·-它如何排列-晶系与结构" aria-label="Permalink to &quot;02 · 它如何排列：晶系与结构&quot;">​</a></h2><p>晶体结构描述原子或离子在空间中的有序排列。宝石学中常用七大晶系来描述晶体对称性；欧泊、黑曜石和琥珀等非晶质或类矿物材料，则需要单独理解。</p><table tabindex="0"><thead><tr><th>晶系</th><th>代表宝石</th><th>观察提示</th></tr></thead><tbody><tr><td>等轴晶系</td><td>钻石、尖晶石、石榴石</td><td>三个轴长度相等，方向关系对称</td></tr><tr><td>四方晶系</td><td>锆石、金红石</td><td>两个轴相等，第三轴不同</td></tr><tr><td>斜方晶系</td><td>坦桑石、亚历山大石、托帕石</td><td>三个轴长度不同，彼此垂直</td></tr><tr><td>六方晶系</td><td>绿柱石、磷灰石</td><td>六重对称轴是重要特征</td></tr><tr><td>三方晶系</td><td>红宝石、蓝宝石、石英、电气石</td><td>以三重对称性识别</td></tr><tr><td>单斜晶系</td><td>正长石、锂辉石</td><td>轴间夹角并非全部为直角</td></tr><tr><td>三斜晶系</td><td>蓝晶石、绿松石</td><td>对称性最低，三个轴均不等且不垂直</td></tr><tr><td>非晶质 / 类矿物</td><td>欧泊、黑曜石、琥珀</td><td>不具备完整的长程晶体有序结构</td></tr></tbody></table><p><em>从<a href="./crystal-systems/cubic.html">等轴晶系</a>开始，逐页观察晶体结构与宝石性质的关系。</em></p><h2 id="_03-·-它如何呈现光-光学现象" tabindex="-1">03 · 它如何呈现光：光学现象 <a class="header-anchor" href="#_03-·-它如何呈现光-光学现象" aria-label="Permalink to &quot;03 · 它如何呈现光：光学现象&quot;">​</a></h2><p>光学现象是观察宝石的重要入口，但现象名称、成因和商业名称不应混为一谈。本项目将“看见的效果”与“产生效果的结构或包裹体”分开记录。</p><table tabindex="0"><thead><tr><th>现象</th><th>主要表现</th><th>代表材料</th></tr></thead><tbody><tr><td>星光效应</td><td>光线形成交叉星芒</td><td>星光红宝石、星光蓝宝石</td></tr><tr><td>猫眼效应</td><td>出现一条可移动的亮带</td><td>猫眼金绿宝石、虎睛石</td></tr><tr><td>变色效应</td><td>在不同光源下呈现不同颜色</td><td>亚历山大石、变色蓝宝石</td></tr><tr><td>变彩 / 游彩</td><td>宝石表面或内部出现随角度变化的彩色闪光</td><td>欧泊</td></tr><tr><td>晕彩</td><td>薄层或层状结构产生彩虹般的干涉色</td><td>拉长石等</td></tr><tr><td>月光效应</td><td>出现柔和的蓝白色漂浮光晕</td><td>月光石</td></tr><tr><td>砂金效应</td><td>内部片状包裹体产生闪烁</td><td>砂金石、日光石</td></tr></tbody></table><p><em>进入<a href="./optical-phenomena/intro.html">光学现象</a>，查看各类效果的成因、观察方式与鉴定提示。</em></p><h2 id="_04-·-它为何有色-颜色成因" tabindex="-1">04 · 它为何有色：颜色成因 <a class="header-anchor" href="#_04-·-它为何有色-颜色成因" aria-label="Permalink to &quot;04 · 它为何有色：颜色成因&quot;">​</a></h2><p>颜色不是孤立的外观标签，而是光与物质相互作用后的结果。常见致色机制包括：</p><table tabindex="0"><thead><tr><th>机制</th><th>核心问题</th><th>代表方向</th></tr></thead><tbody><tr><td>过渡金属离子</td><td>晶格中的离子选择性吸收哪些可见光</td><td>铬、铁、锰、钴、铜等</td></tr><tr><td>色心</td><td>晶格缺陷如何改变光的吸收</td><td>空位、间隙与辐照相关缺陷</td></tr><tr><td>电荷转移</td><td>电子在相邻离子或能级之间如何跃迁</td><td>金属—金属、氧—金属等</td></tr></tbody></table><p>颜色分类适合帮助观察和检索，但不能替代鉴定。真正的颜色描述还要结合色相、明度、饱和度、光源和观察方向。</p><p><em>详见<a href="./color-causes/intro.html">颜色成因</a>，从物理化学机制理解宝石为什么会呈现不同颜色。</em></p><h2 id="_05-·-从分类坐标进入宝石名录" tabindex="-1">05 · 从分类坐标进入宝石名录 <a class="header-anchor" href="#_05-·-从分类坐标进入宝石名录" aria-label="Permalink to &quot;05 · 从分类坐标进入宝石名录&quot;">​</a></h2><p>同一颗宝石可以同时拥有多个坐标：例如欧泊属于非晶质材料，也可能呈现变彩 / 游彩；蓝宝石属于刚玉族，并具有三方晶系。分类不是把宝石放进唯一的盒子，而是建立多维检索关系。</p><p>GemAtlas 中的每颗宝石都拥有独立页面，展示其物理性质、光学特征、处理方式与参考文献。你可以按<a href="./mineral-groups/intro.html">矿物分类组</a>、<a href="./crystal-systems/cubic.html">晶系</a>或<a href="./optical-phenomena/intro.html">光学现象</a>继续探索；准备浏览完整收录对象时，可进入<a href="./../gems/">宝石名录</a>。</p><div class="classification-index-cta"><span class="classification-index-cta__count">60</span><div><strong>宝石名录 · The Stone Index</strong><p>全部 60 种宝石集中于一个可浏览的学习入口，从名称、矿物族到独立详页逐层展开。</p></div><a href="../gems/">浏览全部收录 ↗</a></div>',23)])])}const f=a(s,[["render",o]]);export{b as __pageData,f as default};
